import java.util.*;
import java.io.*;

public class Cutting{

    public static int[] parseStringToIntArray(String s){
        String[] tokens = s.trim().split("\\s+");
        int[] nums = new int[tokens.length];
        for(int i=0; i<tokens.length; i++){
            nums[i] = Integer.parseInt(tokens[i]);
        }
        return nums;
    }

    boolean checkBalance(int[] array, int index){
        int evenCount = 0, oddCount = 0;
        for(int i=0; i<=index; i++){
            if(array[i] % 2 == 0) evenCount++;
            else oddCount++;
        }
        return evenCount == oddCount;
    }

    int findCutIndex(int[] array, int coinsLeft, Map<Integer,Boolean> used){
        int minIdx = -1;
        int minCost = coinsLeft + 1;
        for(int i=1; i<array.length - 1; i++){
            int cost = Math.abs(array[i] - array[i+1]);
            if(cost < minCost && checkBalance(array, i) && !used.containsKey(i)){
                minCost = cost;
                minIdx = i;
            }
        }
        return minIdx;
    }

    public int maxNumberOfCuts(int n, int b, int[] a){
        int coins = b;
        int cuts = 0;
        Map<Integer,Boolean> usedIndices = new HashMap<>();
        while(coins > 0){
            int idx = findCutIndex(a, coins, usedIndices);
            if(idx >= 0){
                usedIndices.put(idx, true);
                int cost = Math.abs(a[idx] - a[idx+1]);
                coins -= cost;
                cuts++;
            } else {
                break;
            }
        }
        return cuts;
    }

    public static void main(String[] args) throws Exception{
        Scanner scanner = new Scanner(System.in);
        String line1 = scanner.nextLine();
        String line2 = scanner.nextLine();
        int[] nB = parseStringToIntArray(line1);
        int[] a = parseStringToIntArray(line2);
        Cutting c = new Cutting();
        int n = nB[0];
        int b = nB[1];
        System.out.println(c.maxNumberOfCuts(n, b, a));
        scanner.close();
    }
}
